steps.sampleSolution:
func somarPositivos(nums ...int) (int, error) {
    if len(nums) == 0 {
        return 0, fmt.Errorf("lista vazia")
    }
    total := 0
    for _, n := range nums {
        total += n
    }
    return total, nil
}
